INSERT INTO `chat_message` (`conversation_uuid`, `user_uuid`, `message`, `time`, `is_img`, `is_read`) VALUES
('c0000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '我十点左右经过南门，可以帮你取。', '2026-06-08 10:36:00', 0, 1),
('c0000000-0000-0000-0000-000000000001', '22222222-2222-2222-2222-222222222222', '可以的，我先看一下申请，确认后把取件码给你。', '2026-06-08 10:45:00', 0, 0),
('c0000000-0000-0000-0000-000000000002', '11111111-1111-1111-1111-111111111111', '耳机电池续航大概还能用多久？', '2026-06-08 09:25:00', 0, 1),
('c0000000-0000-0000-0000-000000000002', '33333333-3333-3333-3333-333333333333', '降噪开着差不多 4 个小时，盒子能充三四次。', '2026-06-08 09:40:00', 0, 0),
('c0000000-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', '我可以今晚先试讲半小时，你看合不合适。', '2026-06-08 08:35:00', 0, 1),
('c0000000-0000-0000-0000-000000000003', '55555555-5555-5555-5555-555555555555', '好，我主要想补导数和积分应用题。', '2026-06-08 08:55:00', 0, 0),
('c0000000-0000-0000-0000-000000000004', '55555555-5555-5555-5555-555555555555', '我已经同意你的申请了，取件码现在详情里可以看到。', '2026-06-08 11:06:00', 0, 1),
('c0000000-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', '收到，我取到后拍照确认。', '2026-06-08 11:08:00', 0, 0),
('c0000000-0000-0000-0000-000000000005', '55555555-5555-5555-5555-555555555555', '后端我可以做，接口文档需要一起定一下。', '2026-06-08 13:22:00', 0, 1),
('c0000000-0000-0000-0000-000000000005', '11111111-1111-1111-1111-111111111111', '可以，今晚我把页面流程发你，我们先拆接口。', '2026-06-08 13:35:00', 0, 0),
('c0000000-0000-0000-0000-000000000006', '33333333-3333-3333-3333-333333333333', '我可以做图表和论文排版，有过一次校赛经验。', '2026-06-08 08:15:00', 0, 1),
('c0000000-0000-0000-0000-000000000006', '77777777-7777-7777-7777-777777777777', '太好了，我们现在缺的就是这一块。', '2026-06-08 08:30:00', 0, 0);
